import socket
import threading

def spy_port(host, port):
    """监听指定端口并获取数据。使用 TCP 握手和 ESMTP 认证。"""
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5)  # 超时设置
        result = sock.connect_ex((host, port))
        if result == 0:
            print(f"已连接到 {host}:{port}")
            sock.close()
        else:
            print(f"连接失败: {host}:{port}")
    except socket.gaierror:
        print(f"DNS 错误: {host}")
    except Exception as e:
        print(f"发生错误: {e}")

def main():
    """监听所有可能可增长的TCP端口，并用于监控成瘾应用程序。"""
    ports = [21, 22, 80, 8080, 80, 443, 53] # 常用端口

    for port in ports:
        spy_port(port, port)

if __name__ == "__main__":
    main()

